import {
  type AuthoringArtifact,
  type FoldIssue,
  attach,
  requiredFieldsIssues,
  universalFoldsIssues,
} from './marketplace-tier.js';

// ─── Required-field sets (the source of the effective-required manifest) ─────

/** standardFloor — the upstream-base always-required fields (code.claude.com hooks). */
export const HOOK_CONFIG_BASE_REQUIRED = ['event', 'matcher', 'type', 'command'] as const;

/** The IS-overlay required delta (beyond the base floor). */
export const HOOK_CONFIG_OVERLAY_REQUIRED = [
  'description',
  'enabled',
  'timeout',
  'blocking',
] as const;

/** Effective required = base ∪ overlay = the IS 8-field marketplace set (NON-NEGOTIABLE). */
export const HOOK_CONFIG_REQUIRED_FIELDS = [
  ...HOOK_CONFIG_BASE_REQUIRED,
  ...HOOK_CONFIG_OVERLAY_REQUIRED,
] as const;

// ─── Constraint constants (mirror the JSON Schemas exactly) ──────────────────

/** code.claude.com hooks event allowed values (upstream-base). */
export const HOOK_EVENT_VALUES = [
  'SessionStart',
  'Setup',
  'UserPromptSubmit',
  'UserPromptExpansion',
  'PreToolUse',
  'PermissionRequest',
  'PermissionDenied',
  'PostToolUse',
  'PostToolUseFailure',
  'PostToolBatch',
  'Notification',
  'MessageDisplay',
  'SubagentStart',
  'SubagentStop',
  'TaskCreated',
  'TaskCompleted',
  'Stop',
  'StopFailure',
  'TeammateIdle',
  'InstructionsLoaded',
  'ConfigChange',
  'CwdChanged',
  'FileChanged',
  'WorktreeCreate',
  'WorktreeRemove',
  'PreCompact',
  'PostCompact',
  'Elicitation',
  'ElicitationResult',
  'SessionEnd',
] as const;
/** code.claude.com hooks type allowed values (upstream-base). */
export const HOOK_TYPE_VALUES = ['command', 'http', 'mcp_tool', 'prompt', 'agent'] as const;

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

// ─── Layer 1: upstream base (authored by THEM) ───────────────────────────────

/**
 * The code.claude.com hooks projection (one flattened handler entry). Required
 * presence of the trigger+handler surface ([event, matcher, type, command]) +
 * type/constraint on the upstream-owned fields (event enum, non-empty matcher,
 * type enum {command,http,mcp_tool,prompt,agent}, non-empty command). This
 * contract carries no `name` — a hook handler has no public identifier, so the
 * universal securityChecks name fold simply does not fire. Length of
 * `description` is intentionally NOT capped here — the universal disclosureMarkers
 * fold (1536) is the operative cap.
 */
export function upstreamBaseIssues(artifact: AuthoringArtifact): FoldIssue[] {
  const issues: FoldIssue[] = [...requiredFieldsIssues(artifact, HOOK_CONFIG_BASE_REQUIRED)];

  if ('event' in artifact) {
    const event = artifact['event'];
    if (typeof event !== 'string') {
      issues.push({ message: 'event must be a string', path: ['event'] });
    } else if (!(HOOK_EVENT_VALUES as readonly string[]).includes(event)) {
      issues.push({
        message: `event must be one of: ${HOOK_EVENT_VALUES.join(', ')}`,
        path: ['event'],
      });
    }
  }

  if ('matcher' in artifact) {
    const matcher = artifact['matcher'];
    if (typeof matcher !== 'string') {
      issues.push({ message: 'matcher must be a string', path: ['matcher'] });
    } else if (matcher.length < 1) {
      issues.push({ message: 'matcher must not be empty', path: ['matcher'] });
    }
  }

  if ('type' in artifact) {
    const type = artifact['type'];
    if (typeof type !== 'string') {
      issues.push({ message: 'type must be a string', path: ['type'] });
    } else if (!(HOOK_TYPE_VALUES as readonly string[]).includes(type)) {
      issues.push({
        message: `type must be one of: ${HOOK_TYPE_VALUES.join(', ')}`,
        path: ['type'],
      });
    }
  }

  if ('command' in artifact) {
    const command = artifact['command'];
    if (typeof command !== 'string') {
      issues.push({ message: 'command must be a string', path: ['command'] });
    } else if (command.length < 1) {
      issues.push({ message: 'command must not be empty', path: ['command'] });
    }
  }

  if ('metadata' in artifact && !isPlainObject(artifact['metadata'])) {
    issues.push({ message: 'metadata must be an object', path: ['metadata'] });
  }

  return issues;
}

// ─── Layer 3: IS overlay (authored by US) ────────────────────────────────────

/**
 * The IS-only delta: `timeout` promoted from upstream-optional to IS-required
 * (non-negative integer) + three net-new IS-required operational/tracking fields
 * (description, enabled, blocking). A field whose type is already enforced by the
 * base (the overlay only adds it to required) is not re-typed here — its presence
 * is the required check — to keep messages single-sourced.
 */
export function isOverlayIssues(artifact: AuthoringArtifact): FoldIssue[] {
  const issues: FoldIssue[] = [...requiredFieldsIssues(artifact, HOOK_CONFIG_OVERLAY_REQUIRED)];

  if ('description' in artifact && typeof artifact['description'] !== 'string') {
    issues.push({ message: 'description must be a string', path: ['description'] });
  }

  if ('enabled' in artifact && typeof artifact['enabled'] !== 'boolean') {
    issues.push({ message: 'enabled must be a boolean', path: ['enabled'] });
  }

  if ('timeout' in artifact) {
    const timeout = artifact['timeout'];
    if (typeof timeout !== 'number' || !Number.isInteger(timeout)) {
      issues.push({ message: 'timeout must be an integer', path: ['timeout'] });
    } else if (timeout < 0) {
      issues.push({ message: 'timeout must be at least 0', path: ['timeout'] });
    }
  }

  if ('blocking' in artifact && typeof artifact['blocking'] !== 'boolean') {
    issues.push({ message: 'blocking must be a boolean', path: ['blocking'] });
  }

  return issues;
}

// ─── The composition (allOf of base + universal folds + overlay) ─────────────

/** Every issue from the three composed layers, in layer order. */
export function hookConfigIssues(artifact: AuthoringArtifact): FoldIssue[] {
  return [
    ...upstreamBaseIssues(artifact),
    ...universalFoldsIssues(artifact),
    ...isOverlayIssues(artifact),
  ];
}

/** The hook-config contract — pure allOf composition (base ∧ universalFolds ∧ overlay). */
export const HookConfigSchema = attach(hookConfigIssues);

export type HookConfig = AuthoringArtifact;
